const users = pm.response.json();

// Check response status
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// Check response is not empty
pm.test("Users list is not empty", function () {
    pm.expect(users).to.be.an("array").that.is.not.empty;
});

// Validate first user's information
pm.test("First user has valid information", function () {
    pm.expect(users[0]).to.have.property("id");
    pm.expect(users[0]).to.have.property("name");
    pm.expect(users[0]).to.have.property("email");
});

// Validate user ID
pm.test("User ID is a number", function () {
    pm.expect(users[0].id).to.be.a("number");
});

// Save first user's ID for the next request
pm.collectionVariables.set("userId", users[0].id);

console.log("Saved User ID:", users[0].id);

pm.collectionVariables.set("userPhone", users[0].phone);

const user = pm.response.json();

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("User ID matches saved ID", function () {
    pm.expect(user.id).to.eql(
        Number(pm.collectionVariables.get("userId"))
    );
});

pm.test("User name is not empty", function () {
    pm.expect(user.name).to.be.a("string").and.not.empty;
});

pm.test("User email is valid", function () {
    pm.expect(user.email).to.be.a("string").and.include("@");
});

console.log("Retrieved User:", user.name);

const updatedUser = pm.response.json();

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("User ID remains unchanged", function () {
    pm.expect(updatedUser.id).to.eql(
        Number(pm.collectionVariables.get("userId"))
    );
});

pm.test("Updated name matches", function () {
    pm.expect(updatedUser.name).to.eql("Updated Test User");
});

pm.test("Updated email matches", function () {
    pm.expect(updatedUser.email).to.eql("updateduser@example.com");
});

pm.test("Phone number is not empty", function () {
    pm.expect(updatedUser.phone).to.be.a("string").and.not.empty;
});

pm.test("Company name is updated", function () {
    pm.expect(updatedUser.company.name).to.eql("Updated Test Company");
});
